func (c *ChainConfig) setNilHardforkTimestampsToDefault(s *SuperchainConfig) {
	// Both the chain overrides and the superchain defaults are the same
	// HardForkConfiguration struct, so we can iterate over their fields in
	// lockstep and fill in any unspecified (nil) override from the default.
	overrides := reflect.ValueOf(&c.HardForkConfiguration).Elem()
	defaults := reflect.ValueOf(&s.hardForkDefaults).Elem()

	for i := 0; i < overrides.NumField(); i++ {
		override := overrides.Field(i)
		if override.IsNil() {
			override.Set(defaults.Field(i))
		}
	}

	// This achieves:

	// if c.CanyonTime == nil {
	// 	c.CanyonTime = s.Config.hardForkDefaults.CanyonTime
	// }
	//
	// ...etc for each field in HardForkConfiguration
}
